// ../postflop-library/pf-src7/src/lib/poker/cards.ts
function choose(n, k) {
  if (k < 0 || k > n) return 0;
  const kk = Math.min(k, n - k);
  let result = 1;
  for (let i = 1; i <= kk; i += 1) result = result * (n - kk + i) / i;
  return Math.round(result);
}

